// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.orchestratorimport com.roshan.persona.brain.trace.BrainTraceimport com.roshan.persona.brain.trace.Layerimport com.roshan.persona.brain.trace.LayerDecisionimport timber.log.Timberimport java.util.concurrent.ConcurrentHashMapimport java.util.concurrent.atomic.AtomicLongimport java.util.concurrent.atomic.AtomicReferenceimport java.util.concurrent.atomic.LongAdderimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Brain metrics (per-layer performance tracking). * * Tracks real-time metrics for every brain request: *   - Per-layer invocation count, success/failure rate *   - Per-layer latency (p50/p95/p99) *   - Cloud fallback rate (L3 → L4 deferral percentage) *   - Budget exhaustion events *   - Total cost, tokens, requests * * ## Use Cases * *   - **Debugging**: "Why is everything going to cloud?" → check L3 failure rate *   - **Optimization**: "L1 is slow" → check L1 p95 latency *   - **Alerts**: "Cloud fallback > 30%" → local model needs improvement *   - **User transparency**: Settings → AI → Performance shows these metrics * * ## Persistence * * In-memory for Module 2. Real impl persists to Room (brain_metrics table) * in Module 3 with hourly aggregation for long-term trends. * * @see <a href="docs/spec/module2-spec-review.pdf">§10.4 BrainMetrics</a> */@Singletonclass BrainMetrics @Inject constructor() {    // Per-layer counters    private val layerInvocations = ConcurrentHashMap<Layer, LongAdder>()    private val layerSuccesses = ConcurrentHashMap<Layer, LongAdder>()    private val layerFailures = ConcurrentHashMap<Layer, LongAdder>()    private val layerLatencies = ConcurrentHashMap<Layer, MutableList<Long>>()    // Aggregate counters    private val totalRequests = AtomicLong(0)    private val totalSuccesses = AtomicLong(0)    private val totalFailures = AtomicLong(0)    private val totalCostUsd = AtomicReference(0.0)    private val totalTokensGenerated = AtomicLong(0)    private val budgetExhaustionCount = AtomicLong(0)    private val cancellationCount = AtomicLong(0)    private val cloudFallbackCount = AtomicLong(0)  // L3 failed → L4 invoked    /**     * Record metrics from a completed [BrainTrace].     *     * Called by [BrainOrchestrator] after every request.     */    @Synchronized    fun record(trace: BrainTrace) {        totalRequests.incrementAndGet()        if (trace.isSuccess) totalSuccesses.incrementAndGet()        else totalFailures.incrementAndGet()        totalCostUsd.set(totalCostUsd.get() + trace.totalCostUsd.toDouble())        totalTokensGenerated.addAndGet(trace.totalTokensGenerated.toLong())        // Track per-layer metrics        var previousLayerDeferred = false        for (layerTrace in trace.layers) {            val layer = layerTrace.layer            layerInvocations.computeIfAbsent(layer) { LongAdder() }.increment()            when (layerTrace.decision) {                LayerDecision.PROCEED -> {                    layerSuccesses.computeIfAbsent(layer) { LongAdder() }.increment()                }                LayerDecision.FAIL -> {                    layerFailures.computeIfAbsent(layer) { LongAdder() }.increment()                }                LayerDecision.DEFER -> {                    previousLayerDeferred = true                }                LayerDecision.SKIP -> { /* not counted as invocation */ }            }            // Track cloud fallback (L3 deferred to L4)            if (layer == Layer.LOCAL_LLM && layerTrace.decision == LayerDecision.DEFER) {                cloudFallbackCount.incrementAndGet()            }            // Track latency            layerTrace.durationMs?.let { latency ->                layerLatencies.computeIfAbsent(layer) { mutableListOf() }.add(latency)                // Keep only last 1000 samples per layer (memory bound)                val samples = layerLatencies[layer] ?: mutableListOf()                if (samples.size > 1000) {                    samples.removeAt(0)                }            }        }        Timber.tag("NOUS.Metrics").v(            "Recorded trace: total=%d, success=%d, fail=%d, cost=\$%.4f",            totalRequests.get(), totalSuccesses.get(), totalFailures.get(), totalCostUsd.get(),        )    }    /**     * Record a budget exhaustion event.     */    fun recordBudgetExhaustion() {        budgetExhaustionCount.incrementAndGet()    }    /**     * Record a user cancellation (barge-in).     */    fun recordCancellation() {        cancellationCount.incrementAndGet()    }    /**     * Get aggregate stats (for Settings → AI → Performance).     */    @Synchronized    fun getAggregateStats(): AggregateStats {        return AggregateStats(            totalRequests = totalRequests.get(),            totalSuccesses = totalSuccesses.get(),            totalFailures = totalFailures.get(),            totalCostUsd = totalCostUsd.get().toFloat(),            totalTokensGenerated = totalTokensGenerated.get(),            budgetExhaustionCount = budgetExhaustionCount.get(),            cancellationCount = cancellationCount.get(),            cloudFallbackCount = cloudFallbackCount.get(),            cloudFallbackRate = computeCloudFallbackRate(),        )    }    /**     * Get per-layer stats.     */    @Synchronized    fun getLayerStats(layer: Layer): LayerStats? {        val invocations = layerInvocations[layer]?.sum() ?: 0L        if (invocations == 0L) return null        val successes = layerSuccesses[layer]?.sum() ?: 0L        val failures = layerFailures[layer]?.sum() ?: 0L        val latencies = layerLatencies[layer]?.toList() ?: emptyList()        return LayerStats(            layer = layer,            invocations = invocations,            successes = successes,            failures = failures,            successRate = if (invocations > 0) successes.toFloat() / invocations else 0f,            failureRate = if (invocations > 0) failures.toFloat() / invocations else 0f,            p50LatencyMs = percentile(latencies, 50),            p95LatencyMs = percentile(latencies, 95),            p99LatencyMs = percentile(latencies, 99),            avgLatencyMs = if (latencies.isNotEmpty()) latencies.average().toLong() else 0L,        )    }    /**     * Get all layer stats.     */    @Synchronized    fun getAllLayerStats(): List<LayerStats> {        return Layer.entries.mapNotNull { getLayerStats(it) }    }    /**     * Check if cloud fallback rate exceeds [threshold] (0.0-1.0).     *     * Used for alerts: "Cloud fallback > 30% → local model needs improvement"     */    fun isCloudFallbackRateHigh(threshold: Float = 0.3f): Boolean {        return computeCloudFallbackRate() > threshold    }    /**     * Reset all metrics (for Settings → AI → Reset Stats).     */    @Synchronized    fun reset() {        layerInvocations.clear()        layerSuccesses.clear()        layerFailures.clear()        layerLatencies.clear()        totalRequests.set(0)        totalSuccesses.set(0)        totalFailures.set(0)        totalCostUsd.set(0.0)        totalTokensGenerated.set(0)        budgetExhaustionCount.set(0)        cancellationCount.set(0)        cloudFallbackCount.set(0)    }    // ─── Internal ────────────────────────────────────────────────────────    private fun computeCloudFallbackRate(): Float {        val l3Invocations = layerInvocations[Layer.LOCAL_LLM]?.sum() ?: 0L        if (l3Invocations == 0L) return 0f        return cloudFallbackCount.get().toFloat() / l3Invocations    }    private fun percentile(values: List<Long>, p: Int): Long {        if (values.isEmpty()) return 0L        val sorted = values.sorted()        val index = (p / 100.0 * (sorted.size - 1)).toInt().coerceIn(0, sorted.size - 1)        return sorted[index]    }    /**     * Aggregate stats across all requests.     */    data class AggregateStats(        val totalRequests: Long,        val totalSuccesses: Long,        val totalFailures: Long,        val totalCostUsd: Float,        val totalTokensGenerated: Long,        val budgetExhaustionCount: Long,        val cancellationCount: Long,        val cloudFallbackCount: Long,        val cloudFallbackRate: Float,    ) {        val successRate: Float get() = if (totalRequests > 0) totalSuccesses.toFloat() / totalRequests else 0f        val failureRate: Float get() = if (totalRequests > 0) totalFailures.toFloat() / totalRequests else 0f    }    /**     * Per-layer stats.     */    data class LayerStats(        val layer: Layer,        val invocations: Long,        val successes: Long,        val failures: Long,        val successRate: Float,        val failureRate: Float,        val p50LatencyMs: Long,        val p95LatencyMs: Long,        val p99LatencyMs: Long,        val avgLatencyMs: Long,    )}